import pickle
from collections import defaultdict

allq = pickle.load(open('/tmp/allq.pkl','rb'))

def eval_method(fn, qs):
    correct=0
    for q in qs:
        ans = fn(q['samples'])
        if ans==q['correct_answer']:
            correct+=1
    return correct/len(qs)

def variant_diversity_then_score(samples):
    best = defaultdict(lambda: -1e9)
    for s in samples:
        key=(s['answer'], s['variant'])
        if s['score']>best[key]:
            best[key]=s['score']
    variants_supporting=defaultdict(set)
    sums=defaultdict(float)
    for (a,v), sc in best.items():
        variants_supporting[a].add(v)
        sums[a]+=sc
    return max(sums.keys(), key=lambda a: (len(variants_supporting[a]), sums[a]))

def sum_per_variant_max_thresh(samples, thresh):
    best = defaultdict(lambda: -1e9)
    for s in samples:
        key=(s['answer'], s['variant'])
        if s['score']>best[key]:
            best[key]=s['score']
    sums=defaultdict(float)
    for (a,v), sc in best.items():
        if sc>thresh:
            sums[a]+=sc
        else:
            sums[a]+=sc*0.2  # downweight but not fully drop
    if not sums:
        return None
    return max(sums.items(), key=lambda kv: kv[1])[0]

def sum_per_variant_max(samples):
    best = defaultdict(lambda: -1e9)
    for s in samples:
        key=(s['answer'], s['variant'])
        if s['score']>best[key]:
            best[key]=s['score']
    sums=defaultdict(float)
    for (a,v), sc in best.items():
        sums[a]+=sc
    return max(sums.items(), key=lambda kv: kv[1])[0]

print('variant_diversity_then_score', eval_method(variant_diversity_then_score, allq))
for t in [-0.5,0,0.5]:
    print('sum_per_variant_max_thresh t=',t, eval_method(lambda s: sum_per_variant_max_thresh(s,t), allq))
print('sum_per_variant_max baseline', eval_method(sum_per_variant_max, allq))
